const row = $('04. Read — Daily Topic').first()?.json || {};
const config = $('02. Config — Buffer Publishing').first().json;
const request = $('01. Trigger — Review Decision').first().json;
const igRow = $('04a. Read — Instagram Posts').first()?.json || {};
const fbRow = $('04b. Read — Facebook Posts').first()?.json || {};

const contentId = String(request.review_content_id || '').trim();
const version = Number(request.review_version || 0);
const action = String(request.review_action || '').trim().toLowerCase();
const rowContentId = String(row.content_id || '').trim();
const rowVersion = Number(row.version || 0);
const rowFound =
  Boolean(rowContentId) &&
  rowContentId === contentId &&
  rowVersion === version;

const igPostId = String(igRow.post_id || '').trim();
const igStatus = String(igRow.status || '').trim();
const fbPostId = String(fbRow.post_id || '').trim();
const fbStatus = String(fbRow.status || '').trim();
const igRowExists = Boolean(igPostId || igStatus);
const fbRowExists = Boolean(fbPostId || fbStatus);
const anyPosted = igStatus === 'Posted' || fbStatus === 'Posted';
const anyPublishing = igStatus === 'Publishing' || fbStatus === 'Publishing';

let actionRoute = 'reject';
let rejectionReason = 'The requested review row was not found.';

if (rowFound && action === 'deny') {
  if (!anyPosted && !anyPublishing) {
    actionRoute = 'deny';
    rejectionReason = '';
  } else {
    rejectionReason =
      'This post can no longer be disapproved because publishing has already started.';
  }
}

if (rowFound && action === 'approve') {
  if (igRowExists && fbRowExists && igStatus === 'Posted' && fbStatus === 'Posted') {
    actionRoute = 'reject';
    rejectionReason = 'This content is already posted on both Instagram and Facebook.';
  } else {
    actionRoute = 'approve';
    rejectionReason = '';
  }
}

return [
  {
    json: {
      ...config,
      ...request,
      ...row,
      content_id: contentId,
      version,
      review_action: action,
      row_found: rowFound,
      action_route: actionRoute,
      rejection_reason: rejectionReason,
      ig_row_exists: igRowExists,
      fb_row_exists: fbRowExists,
      ig_status: igStatus,
      fb_status: fbStatus,
      existing_buffer_post_id: igPostId,
      existing_facebook_buffer_post_id: fbPostId,
    },
  },
];

const row = $('05. Resolve — Review Row').first().json;
const imageUrl = String(row.image_url || '').trim();

if (!/^https:\/\//i.test(imageUrl)) {
  throw new Error('The image URL is not a valid public HTTPS URL.');
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: imageUrl,
    encoding: null,
    followRedirect: true,
    returnFullResponse: true,
    timeout: 30000,
  });

  const statusCode = Number(response.statusCode || 0);
  const headers = response.headers || {};
  const contentType = String(
    headers['content-type'] || headers['Content-Type'] || '',
  ).toLowerCase();
  const body = response.body;
  const byteLength = Buffer.isBuffer(body)
    ? body.length
    : Buffer.byteLength(String(body || ''));

  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    !contentType.startsWith('image/') ||
    byteLength === 0
  ) {
    throw new Error('Image response did not contain usable image content.');
  }

  return [
    {
      json: {
        ...row,
        image_verified: true,
        image_mime_type: contentType.split(';')[0],
        image_bytes: byteLength,
      },
    },
  ];
} catch (error) {
  throw new Error(
    'The image URL is not anonymously accessible as valid image content.',
  );
}

