const response = $input.first()?.json || {};
const row = $('05. Resolve — Review Row').first().json;
const body = response.body ?? response;
const statusCode = Number(response.statusCode ?? 200);
const attempt = Number($runIndex || 0) + 1;
const maxAttempts = Number(row.buffer_create_max_attempts || 3);
const topError = Array.isArray(body.errors) ? body.errors[0] : null;
const topCode = String(topError?.extensions?.code || '').toUpperCase();
const createResult = body.data?.createPost || null;
const resumedPost = body.data?.post || null;
const createdPost = createResult?.post || null;
const post = resumedPost || createdPost || null;
const typedName = String(createResult?.__typename || '');
const typedMessage = String(createResult?.message || '');

let createRoute = 'failed';
let failureCode = 'BUFFER_CREATE_FAILED';
let userMessage = 'Buffer could not accept the Instagram post.';
let bufferPostId = String(post?.id || row.existing_buffer_post_id || '').trim();

if (statusCode === 401 || topCode === 'UNAUTHORIZED') {
  failureCode = 'BUFFER_UNAUTHORIZED';
  userMessage = 'Buffer authentication failed. Update the API credential.';
} else if (statusCode === 403 || topCode === 'FORBIDDEN') {
  failureCode = 'BUFFER_FORBIDDEN';
  userMessage = 'Buffer denied permission for the configured Instagram channel.';
} else if (statusCode === 404 || topCode === 'NOT_FOUND') {
  failureCode = 'BUFFER_NOT_FOUND';
  userMessage = 'The configured Buffer channel or post was not found.';
} else if (post?.id) {
  createRoute = 'success';
  failureCode = '';
  userMessage = '';
} else {
  const isRateLimit =
    statusCode === 429 ||
    topCode === 'RATE_LIMIT_EXCEEDED' ||
    typedName === 'LimitReachedError' ||
    /rate limit|too many requests/i.test(typedMessage);
  const isInvalidInput =
    typedName === 'InvalidInputError' ||
    /invalid|is required|must be|not valid/i.test(typedMessage);
  const isTransient =
    statusCode >= 500 ||
    topCode === 'UNEXPECTED' ||
    (!isInvalidInput && !isRateLimit && Boolean(topError || typedMessage));

  if (isInvalidInput) {
    failureCode = 'BUFFER_INVALID_INPUT';
    userMessage = 'Buffer rejected the Instagram post input.';
  } else if ((isRateLimit || isTransient) && attempt < maxAttempts) {
    createRoute = 'retry';
    failureCode = isRateLimit
      ? 'BUFFER_RATE_LIMIT'
      : 'BUFFER_UNEXPECTED';
    userMessage = '';
  } else if (isRateLimit) {
    failureCode = 'BUFFER_RATE_LIMIT';
    userMessage = 'Buffer rate limiting persisted after three attempts.';
  } else if (isTransient) {
    failureCode = 'BUFFER_UNEXPECTED';
    userMessage = 'Buffer could not create the Instagram post after three attempts.';
  }
}

return [
  {
    json: {
      ...row,
      create_route: createRoute,
      create_attempt: attempt,
      buffer_post_id: bufferPostId,
      failure_code: failureCode,
      user_message: userMessage,
    },
  },
];

