const response = $input.first()?.json || {};
const row = $('05. Resolve — Review Row').first().json;
const stored = $('15. Store — Buffer Post ID').first().json;
const body = response.body ?? response;
const statusCode = Number(response.statusCode ?? 200);
const pollCount = Number($runIndex || 0) + 1;
const maxPolls = Number(row.buffer_max_polls || 12);
const maxFailureAttempts = 3;
const topError = Array.isArray(body.errors) ? body.errors[0] : null;
const topCode = String(topError?.extensions?.code || '').toUpperCase();
const post = body.data?.post || null;
const bufferStatus = String(post?.status || '').toLowerCase();

let statusRoute = 'failed';
let failureCode = 'BUFFER_STATUS_FAILED';
let userMessage = 'Buffer could not confirm Instagram delivery.';
let postUrl = String(post?.externalLink || '').trim();
let publishedAt = String(post?.sentAt || '').trim();

if (statusCode === 401 || topCode === 'UNAUTHORIZED') {
  failureCode = 'BUFFER_UNAUTHORIZED';
  userMessage = 'Buffer authentication failed. Update the API credential.';
} else if (statusCode === 403 || topCode === 'FORBIDDEN') {
  failureCode = 'BUFFER_FORBIDDEN';
  userMessage = 'Buffer denied permission to read the Instagram post.';
} else if (statusCode === 404 || topCode === 'NOT_FOUND') {
  failureCode = 'BUFFER_NOT_FOUND';
  userMessage = 'The Buffer post could not be found.';
} else if (bufferStatus === 'sent') {
  statusRoute = 'posted';
  failureCode = '';
  userMessage = '';
  publishedAt =
    publishedAt ||
    DateTime.now().setZone(row.timezone || 'Asia/Manila').toISO();
} else if (bufferStatus === 'error') {
  failureCode = 'BUFFER_DELIVERY_ERROR';
  userMessage = 'Buffer reported that Instagram delivery failed.';
} else {
  const isRateLimit =
    statusCode === 429 || topCode === 'RATE_LIMIT_EXCEEDED';
  const isUnexpected =
    statusCode >= 500 || topCode === 'UNEXPECTED' || Boolean(topError);

  if (
    (isRateLimit || isUnexpected) &&
    pollCount < Math.min(maxFailureAttempts, maxPolls)
  ) {
    statusRoute = 'retry';
    failureCode = isRateLimit
      ? 'BUFFER_RATE_LIMIT'
      : 'BUFFER_UNEXPECTED';
    userMessage = '';
  } else if (isRateLimit) {
    failureCode = 'BUFFER_RATE_LIMIT';
    userMessage = 'Buffer rate limiting persisted after three attempts.';
  } else if (isUnexpected) {
    failureCode = 'BUFFER_UNEXPECTED';
    userMessage = 'Buffer could not report the post status after three attempts.';
  } else if (post?.id && pollCount < maxPolls) {
    statusRoute = 'retry';
    failureCode = '';
    userMessage = '';
  } else if (post?.id) {
    failureCode = 'BUFFER_DELIVERY_TIMEOUT';
    userMessage = 'Instagram delivery was not confirmed within two minutes.';
  }
}

return [
  {
    json: {
      ...row,
      buffer_post_id: String(post?.id || stored.post_id || ''),
      buffer_status: bufferStatus,
      status_route: statusRoute,
      poll_count: pollCount,
      post_url: postUrl,
      published_at: publishedAt,
      failure_code: failureCode,
      user_message: userMessage,
    },
  },
];

